    ScuAst2500V1SCUSYSRSTCTRLMAC2Msk = 0x1 << 12
    // CRT SCU04[13]: Reset CRT controller (default 1).
    ScuAst2500V1SCUSYSRSTCTRLCRTPos = 13
    ScuAst2500V1SCUSYSRSTCTRLCRTMsk = 0x1 << 13
    // USB20HUB SCU04[14]: Reset USB2.0 Hub/Host controller (default 1). Host/Hub selection is SCU90[29].
    ScuAst2500V1SCUSYSRSTCTRLUSB20HUBPos = 14
    ScuAst2500V1SCUSYSRSTCTRLUSB20HUBMsk = 0x1 << 14
