    ScuAst2500V1SCUVGAHANDSHAKE0VIRTUALEDIDENPos = 4
    ScuAst2500V1SCUVGAHANDSHAKE0VIRTUALEDIDENMsk = 0x1 << 4
    // DRAMINITREADY SCU40[6]: SOC firmware initial DRAM status. 0 = DRAM init not ready; 1 = DRAM init ready.
    ScuAst2500V1SCUVGAHANDSHAKE0DRAMINITREADYPos = 6
    ScuAst2500V1SCUVGAHANDSHAKE0DRAMINITREADYMsk = 0x1 << 6
    // DRAMINITBYSOC SCU40[7]: DRAM initial selection. 0 = VBIOS initialises DRAM; 1 = SOC firmware initialises DRAM.
