    WdtAst2500V1WDTCTRLRSTSYSPos = 1
    WdtAst2500V1WDTCTRLRSTSYSMsk = 0x1 << 1
    // WDTINTR WDT0C[2]: Generate interrupt when the counter equals the pre-timeout setting.
    WdtAst2500V1WDTCTRLWDTINTRPos = 2
    WdtAst2500V1WDTCTRLWDTINTRMsk = 0x1 << 2
    // WDTEXT WDT0C[3]: External signal enable after timeout (WDTRST1 pin T22 / WDTRST2 pin R20); pulse width set by RESET_WIDTH. Reserved on WDT3.
    WdtAst2500V1WDTCTRLWDTEXTPos = 3
    WdtAst2500V1WDTCTRLWDTEXTMsk = 0x1 << 3
    // CLK1MHZ WDT0C[4]: Clock select for WDT counter. 0 = PCLK; 1 = 1 MHz. Writable.  The 1 MHz clock requires PCLK > 10 MHz.
    WdtAst2500V1WDTCTRLCLK1MHZPos = 4
    WdtAst2500V1WDTCTRLCLK1MHZMsk = 0x1 << 4
