// wdt_ast2500_v1::WDT_RESET_WIDTH Reset Width Register (WDT18). Bits 31 and 30 only change when bits [31:24] are written with a key: 0xA5 sets bit 31, 0x5A clears it; 0xA8 sets bit 30, 0x8A clears it.
const (
    // WIDTH WDT18[19:0]: Assertion duration of wdt_ext and wdt_rstarm. Default 0xFF (256 us).  Decremented while the pulse is generated.
    WdtAst2500V1WDTRESETWIDTHWIDTHPos = 0
    WdtAst2500V1WDTRESETWIDTHWIDTHMsk = 0xfffff << 0
    // KEY WDT18[31:24] (write): polarity/drive key (0xA5, 0x5A, 0xA8, 0x8A).
    WdtAst2500V1WDTRESETWIDTHKEYPos = 24
    WdtAst2500V1WDTRESETWIDTHKEYMsk = 0xff << 24
    // PUSHPULL WDT18[30] (read): Reset pulse output driving type. 0 = open-drain; 1 = push-pull.
    WdtAst2500V1WDTRESETWIDTHPUSHPULLPos = 30
    WdtAst2500V1WDTRESETWIDTHPUSHPULLMsk = 0x1 << 30
    // ACTIVEHIGH WDT18[31] (read): Reset pulse polarity. 0 = active low; 1 = active high.
    WdtAst2500V1WDTRESETWIDTHACTIVEHIGHPos = 31
    WdtAst2500V1WDTRESETWIDTHACTIVEHIGHMsk = 0x1 << 31
)

// wdt_ast2500_v1::WDT_RESTART Counter Restart Register (WDT08).
const (
    // KEY Write 0x4755 to reload and restart the counter.
    WdtAst2500V1WDTRESTARTKEYPos = 0
    WdtAst2500V1WDTRESTARTKEYMsk = 0xffff << 0
)

// wdt_ast2500_v1::WDT_TIMEOUT_STATUS Timeout Status Register (WDT10).
const (
    // TIMEOUT WDT10[0]: Indicate timeout. 1 = a timeout has occurred.
    WdtAst2500V1WDTTIMEOUTSTATUSTIMEOUTPos = 0
    WdtAst2500V1WDTTIMEOUTSTATUSTIMEOUTMsk = 0x1 << 0
    // BOOT2ND WDT10[1]: Indicate boot code source. 0 = default; 1 = second boot code.  Firmware must clear it (CLEAR_TIMEOUT_STATUS.CLEAR) after jumping to the physical flash address; on WDT2 this restores the CE0/CE1 address mapping.
    WdtAst2500V1WDTTIMEOUTSTATUSBOOT2NDPos = 1
    WdtAst2500V1WDTTIMEOUTSTATUSBOOT2NDMsk = 0x1 << 1
    // INTR WDT10[2]: Indicate interrupt (counter matched the pre-timeout).
    WdtAst2500V1WDTTIMEOUTSTATUSINTRPos = 2
    WdtAst2500V1WDTTIMEOUTSTATUSINTRMsk = 0x1 << 2
    // EVENTCOUNT WDT10[15:8]: Watchdog timeout event counter.
    WdtAst2500V1WDTTIMEOUTSTATUSEVENTCOUNTPos = 8
    WdtAst2500V1WDTTIMEOUTSTATUSEVENTCOUNTMsk = 0xff << 8
)

